CREATE TABLE appointment_slots (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, visit_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, capacity SMALLINT UNSIGNED NOT NULL, reserved_people SMALLINT UNSIGNED NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL DEFAULT 'OPEN', created_by BIGINT UNSIGNED NOT NULL, updated_by BIGINT UNSIGNED NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), CONSTRAINT pk_appointment_slots PRIMARY KEY(id), CONSTRAINT uq_appointment_slots_time UNIQUE(visit_date,start_time,end_time), CONSTRAINT fk_slots_created FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_slots_updated FOREIGN KEY(updated_by) REFERENCES users(id), CONSTRAINT chk_slots_status CHECK(status IN ('OPEN','CLOSED','CANCELLED')), INDEX idx_slots_availability(visit_date,status,reserved_people));
CREATE TABLE appointments (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, appointment_no VARCHAR(32) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, slot_id BIGINT UNSIGNED NOT NULL, visitor_count SMALLINT UNSIGNED NOT NULL DEFAULT 1, contact_name VARCHAR(50) NOT NULL, contact_phone VARCHAR(20) NOT NULL, contact_email VARCHAR(254) NOT NULL, notes VARCHAR(500) NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', cancel_reason VARCHAR(255) NULL, cancelled_at DATETIME(3) NULL, completed_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), CONSTRAINT pk_appointments PRIMARY KEY(id), CONSTRAINT uq_appointments_no UNIQUE(appointment_no), CONSTRAINT fk_appointments_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_appointments_slot FOREIGN KEY(slot_id) REFERENCES appointment_slots(id), CONSTRAINT chk_appointments_status CHECK(status IN ('PENDING','CONFIRMED','CANCELLED','COMPLETED')), INDEX idx_appointments_user_status(user_id,status,created_at), INDEX idx_appointments_slot_status(slot_id,status));
